AnalyzerCustomBeats::AnalyzerCustomBeats(BeatGridMode mode,
        std::unique_ptr<AnalyzerBeatsPlugin> constant,
        std::unique_ptr<AnalyzerBeatsPlugin> variable,
        const BeatGridEvidence* audioEvidence)
        : m_mode(mode),
          m_constant(std::move(constant)),
          m_variable(std::move(variable)),
          m_audioEvidence(audioEvidence) {
}

bool AnalyzerCustomBeats::initialize(audio::SampleRate sampleRate) {
    m_sampleRate = sampleRate;
    m_selected = nullptr;
    m_preparedGrid.reset();
    m_refinementMs = 0;
    return (m_constant || m_variable) &&
            (!m_constant || m_constant->initialize(sampleRate)) &&
            (!m_variable || m_variable->initialize(sampleRate));
}

bool AnalyzerCustomBeats::processSamples(const CSAMPLE* input, SINT count) {
    return (!m_constant || m_constant->processSamples(input, count)) &&
            (!m_variable || m_variable->processSamples(input, count));
}

bool AnalyzerCustomBeats::finalize() {
    return finalizeWithProgress({});
}

bool AnalyzerCustomBeats::finalizeWithProgress(
        const AnalyzerProgressCallback& progress) {
    m_selected = nullptr;
    m_preparedGrid.reset();
    m_refinementMs = 0;
    if (m_mode == BeatGridMode::Constant || !m_variable) {
        if (!m_constant || !m_constant->finalizeWithProgress(progress)) {
            return false;
        }
        m_selected = m_constant.get();
        return true;
    }
    const auto firstProgress = [&progress](double value) {
        if (progress) {
            progress(value * 0.5);
        }
    };
    qInfo() << "Custom beat analysis: finalizing variable model" << m_variable->id();
    if (!m_variable->finalizeWithProgress(
                m_constant ? firstProgress : progress)) {
        return false;
    }
    if (m_constant) {
        firstProgress(1.0);
    }
    qInfo() << "Custom beat analysis: variable model finished";
    m_selected = m_variable.get();
    if (m_mode == BeatGridMode::Auto && m_constant) {
        QElapsedTimer selection;
        selection.start();
        const auto automatic = BeatFactory::makePreferredBeats(
                m_variable->getBeats(), {}, BeatGridMode::Auto, m_sampleRate, true);
        m_refinementMs += selection.nsecsElapsed() / 1e6;
        const bool compareAudio = m_audioEvidence && m_audioEvidence->hasEvidence();
        if ((automatic && automatic->hasConstantTempo()) || compareAudio) {
            const auto secondProgress = [&progress](double value) {
                if (progress) {
                    progress(0.5 + value * 0.5);
                }
            };
            qInfo() << "Custom beat analysis: finalizing constant model" << m_constant->id();
            if (!m_constant->finalizeWithProgress(secondProgress)) {
                m_selected = nullptr;
                return false;
            }
            qInfo() << "Custom beat analysis: constant model finished";
            m_selected = m_constant.get();
            if (compareAudio) {
                selection.restart();
                const auto makeGrid = [this](const AnalyzerBeatsPlugin* plugin,
                                              bool constant) {
                    auto grid =
                            BeatFactory::makePreferredBeats(plugin->getBeats(),
                                    {},
                                    constant,
                                    m_sampleRate,
                                    plugin->preservesBeatPositions());
                    return grid && !plugin->getDownbeats().isEmpty()
                            ? grid->withDownbeats(plugin->getDownbeats())
                            : grid;
                };
                const auto constant = m_audioEvidence->evaluate(
                        makeGrid(m_constant.get(), true), true);
                const auto variable = m_audioEvidence->evaluate(
                        makeGrid(m_variable.get(), false), true);
                const bool useConstant =
                        BeatGridEvidence::preferConstant(constant,
                                variable,
                                automatic && automatic->hasConstantTempo());
                m_selected = useConstant ? m_constant.get() : m_variable.get();
                m_preparedGrid = useConstant ? constant.grid : variable.grid;
                m_refinementMs += selection.nsecsElapsed() / 1e6;
            }
        }
    }
    if (progress) {
        progress(1.0);
    }
    return true;
}

QJsonObject AnalyzerCustomBeats::timingMetrics() const {
    QJsonObject result{{"grid_refinement", m_refinementMs}};
    for (const auto* plugin : {m_constant.get(), m_variable.get()}) {
        if (!plugin)
            continue;
        const auto values = plugin->timingMetrics();
        for (auto it = values.begin(); it != values.end(); ++it) {
            result.insert(it.key(), result.value(it.key()).toDouble() + it.value().toDouble());
        }
    }
    return result;
}

QJsonObject AnalyzerCustomBeats::analysisDiagnostics() const {
    QJsonObject result;
    for (const auto* plugin : {m_constant.get(), m_variable.get()}) {
        if (!plugin)
            continue;
        const auto values = plugin->analysisDiagnostics();
        for (auto it = values.begin(); it != values.end(); ++it)
            result.insert(it.key(), it.value());
    }
    return result;
}

